/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2718-2726`
pub fn BG_SetTorsoAnimTimer(ps: *mut playerState_t, time: c_int) {
    unsafe {
        (*ps).torsoTimer = time;
        // Cap timer to 0 if was counting down, but let it be -1 if that was
        // intentional. NOTENOTE Yeah this seems dumb, but it mirrors SP.
        if (*ps).torsoTimer < 0 && time != -1 {
            (*ps).torsoTimer = 0;
        }
    }
}

