/// Raven `BG_SaberStartTransAnim`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2733-2790`
pub fn BG_SaberStartTransAnim(
    clientNum: c_int,
    saberAnimLevel: c_int,
    weapon: c_int,
    anim: c_int,
    animSpeed: *mut f32,
    broken: c_int,
) {
    use animNumber_t::*;
    unsafe {
        if anim >= BOTH_A1_T__B_ as c_int && anim <= BOTH_ROLL_STAB as c_int {
            if weapon == WP_SABER {
                let mut saber = BG_MySaber(clientNum, 0);
                if !saber.is_null() && (*saber).animSpeedScale != 1.0 {
                    *animSpeed *= (*saber).animSpeedScale;
                }
                saber = BG_MySaber(clientNum, 1);
                if !saber.is_null() && (*saber).animSpeedScale != 1.0 {
                    *animSpeed *= (*saber).animSpeedScale;
                }
            }
        }

        if (anim >= BOTH_T1_BR__R as c_int && anim <= BOTH_T1_BL_TL as c_int)
            || (anim >= BOTH_T2_BR__R as c_int && anim <= BOTH_T2_BL_TL as c_int)
            || (anim >= BOTH_T3_BR__R as c_int && anim <= BOTH_T3_BL_TL as c_int)
        {
            if saberAnimLevel == FORCE_LEVEL_1 {
                *animSpeed *= 1.5;
            } else if saberAnimLevel == FORCE_LEVEL_3 {
                *animSpeed *= 0.75;
            }

            if broken & (1 << brokenLimb_t::BROKENLIMB_RARM as c_int) != 0 {
                *animSpeed *= 0.5;
            } else if broken & (1 << brokenLimb_t::BROKENLIMB_LARM as c_int) != 0 {
                *animSpeed *= 0.65;
            }
        } else if broken != 0 && PM_InSaberAnim(anim) != 0 {
            if broken & (1 << brokenLimb_t::BROKENLIMB_RARM as c_int) != 0 {
                *animSpeed *= 0.5;
            } else if broken & (1 << brokenLimb_t::BROKENLIMB_LARM as c_int) != 0 {
                *animSpeed *= 0.65;
            }
        }
    }
}

/// Raven `BG_SetAnimFinal`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2800-2924`
pub fn BG_SetAnimFinal(
    ps: *mut playerState_t,
    animations: *mut animation_t,
    setAnimParts: c_int,
    anim: c_int,
    setAnimFlags: c_int,
    // default blendTime=350
    mut blendTime: c_int,
) {
    let mut editAnimSpeed: f32 = 1.0;

    if animations.is_null() {
        return;
    }

    unsafe {
        debug_assert!(anim > -1);
        debug_assert!((*animations.offset(anim as isize)).firstFrame > 0
            || (*animations.offset(anim as isize)).numFrames > 0);

        // NOTE: Setting blendTime here breaks actual blending..
        blendTime = 0;

        BG_SaberStartTransAnim(
            (*ps).clientNum,
            (*ps).fd.saberAnimLevel,
            (*ps).weapon,
            anim,
            &mut editAnimSpeed,
            (*ps).brokenLimbs,
        );

        // Set torso anim
        'torso: {
            if setAnimParts & SETANIM_TORSO != 0 {
                // Don't reset if it's already running the anim
                if setAnimFlags & SETANIM_FLAG_RESTART == 0 && (*ps).torsoAnim == anim {
                    break 'torso;
                }
                // or if a more important anim is running
                if setAnimFlags & SETANIM_FLAG_OVERRIDE == 0
                    && ((*ps).torsoTimer > 0 || (*ps).torsoTimer == -1)
                {
                    break 'torso;
                }

                BG_StartTorsoAnim(ps, anim);

                if setAnimFlags & SETANIM_FLAG_HOLD != 0 {
                    let frame = &*animations.offset(anim as isize);
                    if setAnimFlags & SETANIM_FLAG_HOLDLESS != 0 {
                        // Make sure to only wait in full 1/20 sec server frame intervals.
                        let dur0 =
                            (frame.numFrames - 1) as f32 * (frame.frameLerp as f32).abs();
                        let speedDif = dur0 - (dur0 * editAnimSpeed);
                        let dur = dur0 + speedDif;
                        if dur > 1.0 {
                            (*ps).torsoTimer = (dur - 1.0) as c_int;
                        } else {
                            (*ps).torsoTimer = (frame.frameLerp as f32).abs() as c_int;
                        }
                    } else {
                        (*ps).torsoTimer =
                            (frame.numFrames as f32 * (frame.frameLerp as f32).abs()) as c_int;
                    }

                    if (*ps).fd.forcePowersActive & (1 << FP_RAGE) != 0 {
                        (*ps).torsoTimer = ((*ps).torsoTimer as f32 / 1.7) as c_int;
                    }
                }
            }
        }

        // Set legs anim
        'legs: {
            if setAnimParts & SETANIM_LEGS != 0 {
                // Don't reset if it's already running the anim
                if setAnimFlags & SETANIM_FLAG_RESTART == 0 && (*ps).legsAnim == anim {
                    break 'legs;
                }
                // or if a more important anim is running
                if setAnimFlags & SETANIM_FLAG_OVERRIDE == 0
                    && ((*ps).legsTimer > 0 || (*ps).legsTimer == -1)
                {
                    break 'legs;
                }

                BG_StartLegsAnim(ps, anim);

                if setAnimFlags & SETANIM_FLAG_HOLD != 0 {
                    let frame = &*animations.offset(anim as isize);
                    if setAnimFlags & SETANIM_FLAG_HOLDLESS != 0 {
                        // Make sure to only wait in full 1/20 sec server frame intervals.
                        let dur0 =
                            (frame.numFrames - 1) as f32 * (frame.frameLerp as f32).abs();
                        let speedDif = dur0 - (dur0 * editAnimSpeed);
                        let dur = dur0 + speedDif;
                        if dur > 1.0 {
                            (*ps).legsTimer = (dur - 1.0) as c_int;
                        } else {
                            (*ps).legsTimer = (frame.frameLerp as f32).abs() as c_int;
                        }
                    } else {
                        (*ps).legsTimer =
                            (frame.numFrames as f32 * (frame.frameLerp as f32).abs()) as c_int;
                    }

                    // these guys are ok, they don't actually reference pm
                    if PM_RunningAnim(anim) != 0 || PM_WalkingAnim(anim) != 0 {
                        if (*ps).fd.forcePowersActive & (1 << FP_RAGE) != 0 {
                            (*ps).legsTimer = ((*ps).legsTimer as f32 / 1.3) as c_int;
                        } else if (*ps).fd.forcePowersActive & (1 << FP_SPEED) != 0 {
                            (*ps).legsTimer = ((*ps).legsTimer as f32 / 1.7) as c_int;
                        }
                    }
                }
            }
        }
    }
}

